    </tbody></table></div><div class="flex flex-col gap-3 border-t border-green-900/60 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p class="text-sm text-white">Showing <?= $firstStudent ?>–<?= $lastStudent ?> of <?= $totalStudents ?> students</p><nav class="flex flex-wrap items-center gap-1.5" aria-label="Student pages"><?php if ($page > 1): ?><a href="<?= View::escape($paginationUrl($page - 1)) ?>" class="rounded-lg border border-green-800/80 px-3 py-2 text-sm text-green-100 transition hover:border-emerald-400 hover:bg-emerald-400/10">Previous</a><?php else: ?><span class="rounded-lg border border-green-900/50 px-3 py-2 text-sm text-white">Previous</span><?php endif; ?><?php for ($number = max(1, $page - 2); $number <= min($totalPages, $page + 2); $number++): ?><?php if ($number === $page): ?><span class="grid h-9 min-w-9 place-items-center rounded-lg border border-emerald-400/60 bg-emerald-400/15 px-2 text-sm font-semibold text-emerald-100" aria-current="page"><?= $number ?></span><?php else: ?><a href="<?= View::escape($paginationUrl($number)) ?>" class="grid h-9 min-w-9 place-items-center rounded-lg border border-green-900/60 px-2 text-sm text-slate-300 transition hover:border-emerald-400 hover:bg-emerald-400/10"><?= $number ?></a><?php endif; ?><?php endfor; ?><?php if ($page < $totalPages): ?><a href="<?= View::escape($paginationUrl($page + 1)) ?>" class="rounded-lg border border-green-800/80 px-3 py-2 text-sm text-green-100 transition hover:border-emerald-400 hover:bg-emerald-400/10">Next</a><?php else: ?><span class="rounded-lg border border-green-900/50 px-3 py-2 text-sm text-white">Next</span><?php endif; ?></nav></div></section>

